head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > P > accessibility]<br/>accessibility=true 일때 nextTabID 속성을 설정한 경우 위/아래 방향키 대신 Tab/Shift+Tab 키로 아이템 간 포커스가 이동되는지 확인합니다.",
    "validation" : [
        "accessibility=true 일때 nextTabID 속성을 설정하면 위/아래 방향키 대신 Tab, Shift+Tab 키로 아이템 간 포커스가 이동됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof target_next !== 'undefined') {
        target_next.remove();
    }

    // gdl_multiselect 재생성
    $c.gcm.createDataListMultiSelect();

    let properties = {
        accessibility : "true",
        nextTabID : "target_next",
    }

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createLabel('label="* multiselect 영역 클릭하여 focus → Tab 키 입력으로 li 아이템 간 포커스 이동 (nextTabID 설정 시)"', '', 'label1');
    $c.gcm.createLabel('label="* 원하는 위치에서 Space 키 입력 → 해당 아이템 선택"', '', 'label2');
    $c.gcm.createLabel('label="* getValue 버튼 클릭 → 선택된 아이템 value 확인 (Tab 으로 이동한 li 의 value 반환되면 정상)"', '', 'label3');

    $c.gcm.createBasicMultiSelect(cList);
    $c.gcm.createBasicInput('', '', 'target_next');
}



// 선택된 아이템 value / 인덱스 출력 (Tab + Space 결과 검증)
scwin.btn_getValue_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + target1.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex : " + target1.getSelectedIndex());
};
